const raw = $json && typeof $json === 'object' && !Array.isArray($json)
  ? ($json.body ?? $json)
  : null;

const errors = [];
const allowedKeys = new Set([
  'schema',
  'environment',
  'signal_id',
  'instrument',
  'direction',
  'entry_price',
  'stop_loss',
  'take_profit',
  'created_at',
]);

if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  errors.push({ code: 'INVALID_BODY', field: '$', message: 'Expected one JSON object.' });
}

const value = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
for (const key of Object.keys(value)) {
  if (!allowedKeys.has(key)) {
    errors.push({ code: 'UNKNOWN_FIELD', field: key, message: 'Field is not part of the demo contract.' });
  }
}

if (value.schema !== 'pipsync.tradingview.paper-signal.v1') {
  errors.push({ code: 'INVALID_SCHEMA', field: 'schema', message: 'Use pipsync.tradingview.paper-signal.v1.' });
}

if (value.environment === 'live') {
  errors.push({ code: 'LIVE_MODE_REJECTED', field: 'environment', message: 'Live mode is not supported by this demo.' });
} else if (!['paper', 'sandbox'].includes(value.environment)) {
  errors.push({ code: 'INVALID_ENVIRONMENT', field: 'environment', message: 'Use paper or sandbox.' });
}

if (typeof value.signal_id !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{7,63}$/.test(value.signal_id)) {
  errors.push({ code: 'INVALID_SIGNAL_ID', field: 'signal_id', message: 'Use 8-64 safe identifier characters.' });
}

if (typeof value.instrument !== 'string' || !/^[A-Z0-9][A-Z0-9._:/-]{2,19}$/.test(value.instrument)) {
  errors.push({ code: 'INVALID_INSTRUMENT', field: 'instrument', message: 'Use a 3-20 character uppercase instrument.' });
}

if (!['BUY', 'SELL'].includes(value.direction)) {
  errors.push({ code: 'INVALID_DIRECTION', field: 'direction', message: 'Use BUY or SELL.' });
}

const positiveNumber = (candidate) => typeof candidate === 'number' && Number.isFinite(candidate) && candidate > 0;
if (!positiveNumber(value.entry_price)) {
  errors.push({ code: 'INVALID_ENTRY_PRICE', field: 'entry_price', message: 'Use a positive finite number.' });
}

for (const field of ['stop_loss', 'take_profit']) {
  if (Object.prototype.hasOwnProperty.call(value, field) && value[field] !== null && !positiveNumber(value[field])) {
    errors.push({ code: `INVALID_${field.toUpperCase()}`, field, message: 'Use null or a positive finite number.' });
  }
}

if (positiveNumber(value.entry_price) && positiveNumber(value.stop_loss)) {
  if (value.direction === 'BUY' && value.stop_loss >= value.entry_price) {
    errors.push({ code: 'INVALID_STOP_GEOMETRY', field: 'stop_loss', message: 'BUY stop loss must be below entry.' });
  }
  if (value.direction === 'SELL' && value.stop_loss <= value.entry_price) {
    errors.push({ code: 'INVALID_STOP_GEOMETRY', field: 'stop_loss', message: 'SELL stop loss must be above entry.' });
  }
}

if (positiveNumber(value.entry_price) && positiveNumber(value.take_profit)) {
  if (value.direction === 'BUY' && value.take_profit <= value.entry_price) {
    errors.push({ code: 'INVALID_TARGET_GEOMETRY', field: 'take_profit', message: 'BUY take profit must be above entry.' });
  }
  if (value.direction === 'SELL' && value.take_profit >= value.entry_price) {
    errors.push({ code: 'INVALID_TARGET_GEOMETRY', field: 'take_profit', message: 'SELL take profit must be below entry.' });
  }
}

if (typeof value.created_at !== 'string' || !Number.isFinite(Date.parse(value.created_at))) {
  errors.push({ code: 'INVALID_CREATED_AT', field: 'created_at', message: 'Use an ISO 8601 timestamp.' });
}

const accepted = errors.length === 0;
const liveRejected = errors.some((error) => error.code === 'LIVE_MODE_REJECTED');
const safeSignal = accepted
  ? {
      signal_id: value.signal_id,
      environment: value.environment,
      instrument: value.instrument,
      direction: value.direction,
      entry_price: value.entry_price,
      stop_loss: value.stop_loss ?? null,
      take_profit: value.take_profit ?? null,
      created_at: value.created_at,
    }
  : null;

return [{
  json: {
    httpStatus: accepted ? 200 : (liveRejected ? 403 : 400),
    body: {
      schema: 'pipsync.validation-result.v1',
      accepted,
      execution: 'disabled',
      signal: safeSignal,
      errors,
      limitations: {
        authentication: 'not implemented',
        durableReplayProtection: 'not implemented',
        downstreamExecution: 'not implemented',
      },
    },
  },
}];
